import math

def solve():
    option_type = "call"
    asset_price = 150.0
    strike_price = 140.0
    time_to_expiry = 0.5
    volatility = 0.25
    risk_free_rate = 0.02

    # Manual implementation of standard normal cumulative distribution function (CDF)
    # using math.erf, as scipy is not allowed.
    def norm_cdf(x):
        return 0.5 * (1.0 + math.erf(x / math.sqrt(2.0)))

    d1 = (math.log(asset_price / strike_price) + (risk_free_rate + 0.5 * volatility ** 2) * time_to_expiry) / (volatility * math.sqrt(time_to_expiry))

    if option_type.lower() == 'call':
        delta = norm_cdf(d1)
    elif option_type.lower() == 'put':
        delta = norm_cdf(d1) - 1
    else:
        raise ValueError("Invalid option type. Must be 'call' or 'put'.")

    return f"{delta:.4f}"

